(function(root){
'use strict';
const day=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
function weekStart(value){const d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
function filter(rows,{conference='all',week='this',query='',asOf,teams}){const start=weekStart(asOf);return rows.filter(g=>(conference==='all'||[g.away,g.home].some(t=>teams[t]?.conference===conference))&&(week==='all'||(week==='this'?weekStart(day(g.date))===start:weekStart(day(g.date))>start))&&(!query||[g.home,g.away].some(t=>[teams[t]?.name,teams[t]?.abbr].some(n=>n?.toLowerCase().includes(query.toLowerCase())))));}
function selections(g){const p=g.savedPick;if(!p)return null;const s=p.quote?.homeSpread,total=p.quote?.overUnder;return {winner:p.homeMargin===0?null:p.homeMargin>0?g.home:g.away,spread:Number.isFinite(s)&&p.homeMargin+s!==0?{team:p.homeMargin+s>0?g.home:g.away,line:p.homeMargin+s>0?s:-s}:null,total:Number.isFinite(total)&&p.total!==total?{side:p.total>total?'Over':'Under',line:total}:null};}
function state(g){if(g.done)return 'Final';if(/POSTPONED|CANCELED|CANCELLED/.test(g.status||''))return /POSTPONED/.test(g.status)?'Postponed':'Canceled';if(/IN_PROGRESS|HALFTIME|END_PERIOD|DELAYED/.test(g.status||''))return 'In progress at last check';return 'Kickoff passed · awaiting final';}
const api={filter,selections,state};root.StartedGames=api;if(typeof module!=='undefined')module.exports=api;if(typeof document==='undefined')return;
let data,failed=false;
const signed=v=>(v>0?'+':'')+v;
const stamp=v=>v?new Date(v).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET':'time unavailable';
const factorLabels={'Elo difference':'strength based on earlier results','Net success-rate difference':'how consistently the teams moved the ball','Scoring margin difference':'earlier scoring results','Home field':'home-field advantage','Explosive-rate difference':'big plays','Yards/game difference':'offensive yardage','Scoring environment':'the expected scoring pace'};
function card(g){const p=g.savedPick,s=selections(g);return `<article class="started-card"><div class="started-head"><b>${esc(state(g))}</b><span>${esc(stamp(g.date))}</span></div><div class="started-team">${logo(g.away)}${rankedName(g.away,true)}<strong>${g.done?g.awayScore:'—'}</strong></div><div class="started-team">${logo(g.home)}${rankedName(g.home,true)}<strong>${g.done?g.homeScore:'—'}</strong></div><p class="started-check">${g.done?'Final score':'Score not shown · this is not a live feed'} · Checked ${esc(stamp(g.checkedAt))}${g.channels.length?' · '+esc(g.channels.join(' / ')):''}</p>${p?`<div class="started-picks"><div><small>OUR PREGAME WINNER</small><b>${s.winner?esc(name(s.winner)):'No winner selected'}</b></div><div><small>OUR SPREAD PICK</small><b>${s.spread?esc(name(s.spread.team))+' '+signed(s.spread.line):'No saved spread pick'}</b></div><div><small>OUR TOTAL PICK</small><b>${s.total?s.total.side+' '+s.total.line:'No saved total pick'}</b></div></div><p class="started-projection">Saved projection: ${s.winner?esc(name(s.winner))+' by '+GamedayEngine.half(Math.abs(p.homeMargin)):'Even'} · ${GamedayEngine.half(p.total)} total points.</p><details><summary>View the saved pregame analysis</summary><p>Pick made ${esc(stamp(p.forecastAt))}. ${p.archiveType==='recovered_saved_forecast'?'Recovered from an older saved forecast.':'Saved before kickoff.'} These are the original picks, not a forecast rebuilt during the game.</p>${p.drivers.slice().sort((a,b)=>Math.abs(b.points)-Math.abs(a.points)).slice(0,3).map(d=>`<p>${esc(factorLabels[d.name]||d.name)}: moved the predicted margin ${Math.abs(d.points).toFixed(1)} points toward ${esc(name(d.points>=0?g.home:g.away))}.</p>`).join('')}<p>Saved line checked ${esc(stamp(p.quote?.retrievedAt))}${p.quote?.provider?' · '+esc(p.quote.provider):''}.</p><a href="${esc(p.sourceArchive)}" target="_blank" rel="noreferrer">Original forecast file ↗</a></details>`:'<p>No eligible pregame prediction was saved for this game. We will not create one after kickoff.</p>'}<a class="started-source" href="${esc(g.url)}" target="_blank" rel="noreferrer">Game score & box score ↗</a></article>`;}
api.render=()=>{const mount=document.getElementById('startedGames');if(!mount)return;if(!data){mount.innerHTML=failed?'<p class="notice">Started-game history could not load. Reload to try again.</p>':'';return;}const rows=filter(data.games,{conference:$('conference').value,week:$('week').value,query:$('search').value.trim(),asOf:D.asOf,teams:D.teams});mount.innerHTML=rows.length?`<section class="started-section"><div class="eyebrow">PICKS STAY ON THE BOARD</div><h2>Started & finished games <span>${rows.length}</span></h2><p>Kickoff doesn’t erase a pick. See what we chose before the game started. Final results are graded after the next successful refresh.</p><div class="started-grid">${rows.map(card).join('')}</div></section>`:'';};
document.addEventListener('DOMContentLoaded',async()=>{await initialDataReady;if(!D||!M)return;try{const response=await fetch('started-games.json',{cache:'no-cache'});if(!response.ok)throw Error('Started games unavailable');const value=await response.json();if(value.runId!==M.refreshRunId)throw Error('Started games release mismatch');data=value;}catch(error){failed=true;console.warn(error.message);}api.render();},{once:true});
})(globalThis);

